export const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
export const cents=n=>Math.round(Number(n)*100);
export const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
export const monthShift=(m,n)=>{const [y,mo]=m.split('-').map(Number),d=new Date(Date.UTC(y,mo-1+n,1));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`;};
export const monthName=m=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-01T12:00:00Z'));
export const dayInMonth=(m,day)=>{const [y,mo]=m.split('-').map(Number);return `${m}-${String(Math.min(day,new Date(Date.UTC(y,mo,0)).getUTCDate())).padStart(2,'0')}`;};
export function firstInvoice(date,c){if(!c?.dia_fechamento||!c?.dia_vencimento)return '';let m=date.slice(0,7);if(date>=dayInMonth(m,c.dia_fechamento))m=monthShift(m,1);if(dayInMonth(m,c.dia_vencimento)<=dayInMonth(m,c.dia_fechamento))m=monthShift(m,1);return m;}
export function parts(total,n){const a=cents(total),base=Math.floor(a/n);return Array.from({length:n},(_,i)=>(base+(i<a%n?1:0))/100);}
export function delta(m,account){if(['reserva','liberacao'].includes(m.tipo)||m.forma==='credito')return 0;const v=cents(m.valor);if(['transferencia','aporte','resgate'].includes(m.tipo))return (m.destino_id===account?v:0)-(m.conta_id===account?v:0);if(m.conta_id!==account)return 0;return ['entrada','rendimento'].includes(m.tipo)?v:-v;}
export function balances(accounts,rows,date=today()){return accounts.map(a=>{const valid=rows.filter(m=>m.status==='concluido'&&m.data_realizada<=date&&(!a.data_saldo_inicial||m.data_realizada>=a.data_saldo_inicial));const known=a.saldo_inicial!==null&&a.saldo_inicial!==undefined&&a.data_saldo_inicial<=date;const value=(known?cents(a.saldo_inicial):0)+valid.reduce((s,m)=>s+delta(m,a.id),0);return {...a,known,value:value/100};});}
export function reserves(rows,date=today()){const out=new Map();for(const m of rows){if(!m.meta_id||m.status!=='concluido'||m.data_realizada>date)continue;let account,sign=0;if(m.tipo==='aporte'){account=m.destino_id;sign=1;}if(m.tipo==='reserva'){account=m.conta_id;sign=1;}if(m.tipo==='resgate'||m.tipo==='liberacao'){account=m.conta_id;sign=-1;}if(!sign)continue;const key=m.meta_id+'|'+account;out.set(key,(out.get(key)||0)+sign*cents(m.valor));}return [...out].map(([key,value])=>{const [meta_id,conta_id]=key.split('|');return {meta_id,conta_id,value:value/100};});}
export function invoices(rows){const groups=new Map();for(const m of rows){if(!m.cartao_id||!m.fatura_mes||m.status==='cancelado')continue;const key=m.cartao_id+'|'+m.fatura_mes.slice(0,7);if(!groups.has(key))groups.set(key,{cartao_id:m.cartao_id,month:m.fatura_mes.slice(0,7),gross:0,paid:0,planned:0,items:[]});const g=groups.get(key);if(m.tipo==='saida'&&m.forma==='credito'){g.gross+=cents(m.valor);g.items.push(m);}if(m.tipo==='pagamento_fatura'){if(m.status==='concluido')g.paid+=cents(m.valor);else g.planned+=cents(m.valor);}}return [...groups.values()].map(g=>({...g,gross:g.gross/100,paid:g.paid/100,planned:g.planned/100,remaining:Math.max(0,g.gross-g.paid)/100,excess:Math.max(0,g.paid-g.gross)/100})).sort((a,b)=>a.month.localeCompare(b.month));}
export function cashTotals(rows,start,end){const done=rows.filter(m=>m.status==='concluido'&&m.data_realizada>=start&&m.data_realizada<=end);return {income:done.filter(m=>m.tipo==='entrada').reduce((s,m)=>s+cents(m.valor),0)/100,expense:done.filter(m=>['saida','pagamento_fatura'].includes(m.tipo)&&m.forma!=='credito').reduce((s,m)=>s+cents(m.valor),0)/100};}
export function monthEnd(m){return dayInMonth(m,31);}
